/**
 * Frontier Terrain Forge — uniform packing.
 *
 * Offsets are never written by hand here: they come from src/gen/gpu_layout.js,
 * which is generated by reflecting the SPIR-V naga emits for each WGSL module.
 * If a struct member is reordered in a shader, the next `npm run layout` moves
 * the offsets and this packer follows automatically.
 */
import { SHADER_LAYOUTS } from '../gen/gpu_layout.js';

const COMPONENT_COUNT = {
  f32: 1, u32: 1, i32: 1, bool: 1,
  vec2f: 2, vec2u: 2, vec2i: 2,
  vec3f: 3, vec3u: 3,
  vec4f: 4, vec4u: 4, vec4i: 4,
};

const isIntType = (t) => t === 'u32' || t === 'i32' || t === 'vec2u' || t === 'vec3u' || t === 'vec4u' || t === 'vec2i' || t === 'vec3i' || t === 'vec4i';

export class UniformWriter {
  /**
   * @param {GPUDevice} device
   * @param {string} moduleName  e.g. 'passes/terrain_layer.wgsl'
   * @param {string} structName  e.g. 'LayerUniforms'
   * @param {string} [label]
   */
  constructor(device, moduleName, structName, label = structName) {
    const mod = SHADER_LAYOUTS[moduleName];
    if (!mod) throw new Error(`no generated layout for ${moduleName} — run: npm run layout`);
    const struct = mod.structs[structName];
    if (!struct) throw new Error(`no struct ${structName} in ${moduleName}`);
    this.device = device;
    this.moduleName = moduleName;
    this.structName = structName;
    this.struct = struct;
    this.size = Math.max(16, Math.ceil(struct.size / 16) * 16);
    this.buffer = device.createBuffer({
      label: `uniform:${label}`,
      size: this.size,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });
    this.bytes = new ArrayBuffer(this.size);
    this.f32 = new Float32Array(this.bytes);
    this.u32 = new Uint32Array(this.bytes);
    this.i32 = new Int32Array(this.bytes);
  }

  get layout() { return this.struct; }

  _writeScalar(field, value) {
    const offset = field.offset;
    const type = field.wgsl;
    if (field.array) {
      // array<T, N>: `value` is an array of scalars/vectors/objects.
      const stride = field.array.stride || Math.floor(field.size / field.array.count);
      for (let i = 0; i < field.array.count; i++) {
        const item = value?.[i];
        if (item === undefined) continue;
        if (field.fields) this._writeStruct(field.fields, item, offset + i * stride);
        else this._writeVector(type, item, offset + i * stride);
      }
      return;
    }
    if (field.fields) {
      this._writeStruct(field.fields, value, offset);
      return;
    }
    this._writeVector(type, value, offset);
  }

  _writeVector(type, value, offset) {
    const count = COMPONENT_COUNT[type];
    if (count === undefined) return;
    const ints = isIntType(type);
    const target = ints ? this.u32 : this.f32;
    const base = offset / 4;
    if (count === 1) {
      target[base] = value ?? 0;
      return;
    }
    const v = Array.isArray(value) || ArrayBuffer.isView(value) ? value : [value];
    for (let c = 0; c < count; c++) target[base + c] = v[c] ?? 0;
  }

  _writeStruct(fields, values, baseOffset) {
    if (!values) return;
    for (const [name, field] of Object.entries(fields)) {
      const value = values[name];
      if (value === undefined) continue;
      const saved = field.offset;
      this._writeScalar({ ...field, offset: saved + baseOffset }, value);
    }
  }

  /** Write a plain object of values keyed by field name, then upload. */
  write(values = {}) {
    if (values instanceof ArrayBuffer || ArrayBuffer.isView(values)) {
      new Uint8Array(this.bytes).set(new Uint8Array(values.buffer ?? values, values.byteOffset ?? 0, this.size));
    } else {
      for (const [name, field] of Object.entries(this.struct.fields)) {
        const value = values[name];
        if (value === undefined) continue;
        this._writeScalar(field, value);
      }
    }
    this.device.queue.writeBuffer(this.buffer, 0, this.bytes, 0, this.size);
    return this;
  }

  destroy() { this.buffer.destroy(); }
}
